"""Meridian CRM RBAC permission check."""

from typing import Any


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record."""
    role_id = user.get("ROLE_ID", "")

    # DELETE requires a record that is not already soft-deleted.
    # A blank or missing CHAR(1) boolean has the legacy value "N".
    if action == "DELETE":
        del_flg = record.get("DEL_FLG", "")
        if del_flg == "":
            del_flg = "N"
        if del_flg != "N":
            return False

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        # ADMIN bypasses scope only; reaching this branch confirms that the
        # required permission row exists.
        if role_id == "ADMIN":
            return True

        scope: Any = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
        if scope == "OWN":
            return record.get("OWNER_UID", "") == user.get("USR_ID", "")
        return False  # NONE or an unrecognized scope denies.

    # Missing role/object/action permission rows deny, including for ADMIN.
    return False
